const body = $input.first().json.body;
const callback = body?.callback_query;
const data = callback?.data;
const clean = data?.replace(/^=/, '');
const split = clean?.split('|');
const action = split?.[0];
const group_id = split?.[1];
const chat_id = callback?.message?.chat?.id;
const telegram_user_id = callback?.from?.id;
const callback_id = callback?.id;
const message_id = callback?.message?.message_id;

const BOT_TOKEN = '8825541334:AAGtrNwHbAdTURG4p151qWRaJjlh5G8zEWI';
const SUPABASE_URL = 'https://kjmcmmxjxfmssahzefry.supabase.co';
const SUPABASE_KEY = 'TU_KEY_AQUI';

const tg = async (method, params) => {
  return await helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${BOT_TOKEN}/${method}`,
    headers: {'Content-Type': 'application/json'},
    body: params,
    json: true
  });
};

const sb = async (table, method='GET', body_data=null, query='') => {
  return await helpers.httpRequest({
    method,
    url: `${SUPABASE_URL}/rest/v1/${table}${query}`,
    headers: {
      'Content-Type': 'application/json',
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Prefer': method === 'POST' ? 'return=representation' : ''
    },
    body: body_data || undefined,
    json: true
  });
};

if (action === 'vote_favorite') {
  const rec = await sb('group_recommendations', 'GET', null, `?group_id=eq.${group_id}&order=created_at.desc&limit=1`);
  const lugares = rec[0]?.top_lugares || [];
  const inlineKeyboard = lugares.map(l => (
  [{text: l.nombre, callback_data: `vote_place_${l.id}|${group_id}`}]
));
  await tg('sendMessage', {
    chat_id,
    text: '❤️ Selecciona tu lugar favorito:',
    reply_markup: {inline_keyboard: inlineKeyboard}
  });

} else if (action === 'reroll') {
  const rec = await sb('group_recommendations', 'GET', null, 
    `?group_id=eq.${group_id}&order=created_at.desc&limit=1`
  );
  const actuales = (rec[0]?.top_lugares || []).map(l => l.id);
  const vistos = rec[0]?.lugares_vistos || [];
  const exclude = [...new Set([...vistos, ...actuales])];

  const nueva = await helpers.httpRequest({
    method: 'POST',
    url: 'https://cali-match.onrender.com/recomendar',
    headers: {'Content-Type': 'application/json'},
    body: {group_id, exclude_places: exclude},
    json: true
  });

  // Acumular lugares vistos
  const nuevos_ids = (nueva.top_lugares || []).map(l => l.id);
  await sb('group_recommendations', 'PATCH',
    {lugares_vistos: [...exclude, ...nuevos_ids]},
    `?group_id=eq.${group_id}`
  );

  // Resetear votos para la nueva recomendación
  await sb('group_votes', 'DELETE', null, `?group_id=eq.${group_id}`);

  const insights = (nueva.insights || []).slice(0,3).map(i => `✨ ${i}`).join('\n');
  const lugares = (nueva.top_lugares || []).slice(0,4).map((l, idx) => 
    `${idx+1}. ${l.nombre} (${l.match_pct}% match)\n   📍 ${l.barrio} | ${l.categoria}\n   🧠 ${l.descripcion}`
  ).join('\n\n');
  const mensaje = `🔥 CALIMATCH - RESULTADO DEL PARCHE ${group_id}\n\n📊 Score: ${nueva.score}%\n\n────────────────────\n\n💡 Insights:\n${insights}\n\n\n🏆 Mejores lugares:\n\n${lugares}\n\n🍹 ¡Disfruten el parche!`;

  const miembros = await sb('telegram_user_groups', 'GET', null, `?group_id=eq.${group_id}`);
  const nombreSolicitante = callback?.from?.first_name || 'Alguien';

  for (const miembro of miembros) {
    await tg('sendMessage', {
      chat_id: miembro.chat_id,
      text: `🔄 ${nombreSolicitante} pidió una nueva recomendación:\n\n${mensaje}`,
      reply_markup: {inline_keyboard: [[
        {text: '❤️ Votar favorito', callback_data: `vote_favorite|${group_id}`},
        {text: '🔄 Nueva recomendación', callback_data: `reroll|${group_id}`},
        {text: '⭐ Calificar', callback_data: `review|${group_id}`}
      ]]}
    });
  }
} else if (action === 'review') {
  await tg('sendMessage', {
    chat_id,
    text: '⭐ ¿Qué tan satisfecho quedaste?',
    reply_markup: {inline_keyboard: [[
      {text: '1', callback_data: `rating_q1_1|${group_id}`},
      {text: '2', callback_data: `rating_q1_2|${group_id}`},
      {text: '3', callback_data: `rating_q1_3|${group_id}`},
      {text: '4', callback_data: `rating_q1_4|${group_id}`},
      {text: '5', callback_data: `rating_q1_5|${group_id}`}
    ]]}
  });

} else if (action?.startsWith('vote_place_')) {
  const lugar_id = action.replace('vote_place_', '');

  // Verificar si ya votó
  const yaVoto = await sb('group_votes', 'GET', null, 
    `?group_id=eq.${group_id}&telegram_user_id=eq.${telegram_user_id}&limit=1`
  );

  if (yaVoto.length > 0) {
    await tg('answerCallbackQuery', {
      callback_query_id: callback_id,
      show_alert: true,
      text: '❌ Ya votaste anteriormente. Solo se permite un voto por persona.'
    });
  } else {
    // Guardar voto
    await sb('group_votes', 'POST', {group_id, telegram_user_id, lugar_id});

    // Obtener todos los votos del grupo
    const votos = await sb('group_votes', 'GET', null, `?group_id=eq.${group_id}`);

    // Contar votos por lugar
    const conteo = {};
    for (const voto of votos) {
      conteo[voto.lugar_id] = (conteo[voto.lugar_id] || 0) + 1;
    }

    // Obtener nombres de lugares
    const rec = await sb('group_recommendations', 'GET', null, `?group_id=eq.${group_id}&order=created_at.desc&limit=1`);
    const lugares = rec[0]?.top_lugares || [];

    // Construir marcador
    const marcador = lugares
      .map(l => ({
        nombre: l.nombre,
        votos: conteo[String(l.id)] || 0
      }))
      .sort((a, b) => b.votos - a.votos)
      .map((l, i) => `${i === 0 ? '🏆' : `${i + 1}.`} ${l.nombre} — ${l.votos} voto${l.votos !== 1 ? 's' : ''}`)
      .join('\n');
    // Notificar a todos los miembros del grupo excepto al que votó
const miembros = await sb('telegram_user_groups', 'GET', null, `?group_id=eq.${group_id}`);
const nombreVotante = callback?.from?.first_name || 'Alguien';
const lugarVotado = lugares.find(l => String(l.id) === String(lugar_id))?.nombre || 'un lugar';

for (const miembro of miembros) {
  if (String(miembro.chat_id) !== String(chat_id)) {
    await tg('sendMessage', {
      chat_id: miembro.chat_id,
      text: `🗳️ ${nombreVotante} votó por ${lugarVotado}\n\n📊 Marcador actual:\n${marcador}`
    });
  }
}
    await tg('answerCallbackQuery', {
      callback_query_id: callback_id,
      show_alert: true,
      text: `✅ ¡Voto registrado!\n\n📊 Marcador actual:\n${marcador}`
    });
  }

} else if (action?.startsWith('rating_q1_')) {
  const satisfaccion = parseInt(action.replace('rating_q1_', ''));
  const rec = await sb('group_recommendations', 'GET', null, `?group_id=eq.${group_id}&order=created_at.desc&limit=1`);
  const lugar_id = rec[0]?.top_lugares?.[0]?.id;
  await sb('user_ratings_state', 'POST', {telegram_user_id, group_id, lugar_id, satisfaccion, step_actual: 'q2'});
  await tg('editMessageText', {
    chat_id, message_id,
    text: '⭐ ¿Lo recomendarías?',
    reply_markup: {inline_keyboard: [[
      {text: '1', callback_data: `rating_q2_1|${group_id}`},
      {text: '2', callback_data: `rating_q2_2|${group_id}`},
      {text: '3', callback_data: `rating_q2_3|${group_id}`},
      {text: '4', callback_data: `rating_q2_4|${group_id}`},
      {text: '5', callback_data: `rating_q2_5|${group_id}`}
    ]]}
  });

} else if (action?.startsWith('rating_q2_')) {
  const recomendaria = parseInt(action.replace('rating_q2_', ''));
  await sb('user_ratings_state', 'PATCH', {recomendaria, step_actual: 'q3'}, `?telegram_user_id=eq.${telegram_user_id}&group_id=eq.${group_id}`);
  await tg('editMessageText', {
    chat_id, message_id,
    text: '⭐ ¿Coincidía con los gustos del grupo?',
    reply_markup: {inline_keyboard: [[
      {text: '1', callback_data: `rating_q3_1|${group_id}`},
      {text: '2', callback_data: `rating_q3_2|${group_id}`},
      {text: '3', callback_data: `rating_q3_3|${group_id}`},
      {text: '4', callback_data: `rating_q3_4|${group_id}`},
      {text: '5', callback_data: `rating_q3_5|${group_id}`}
    ]]}
  });

} else if (action?.startsWith('rating_q3_')) {
  const coincidencia = parseInt(action.replace('rating_q3_', ''));
  const state = await sb('user_ratings_state', 'GET', null, `?telegram_user_id=eq.${telegram_user_id}&group_id=eq.${group_id}&step_actual=eq.q3&limit=1`);
  await sb('place_ratings', 'POST', {
    telegram_user_id, group_id,
    lugar_id: state[0]?.lugar_id,
    satisfaccion: state[0]?.satisfaccion,
    recomendaria: state[0]?.recomendaria,
    coincidencia
  });
  await tg('editMessageText', {chat_id, message_id, text: '✅ ¡Gracias por tu calificación!'});
}

return [{json: {ok: true, action, group_id}}];
